CREATE OR REPLACE FUNCTION public.welcome_packs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if new.id !~ '^[0-9]{17,20}$' then return new; end if;
  if coalesce(current_setting('tcg.skip_welcome', true), '') = 'on' then return new; end if;
